public class RecursiveDnsResolver {

    private static final int MAX_DEPTH = 20; // protects against referral cycles

    private final DnsCache cache;
    private final DnsServerRef rootServer;

    public RecursiveDnsResolver(DnsCache cache, DnsServerRef rootServer) {
        this.cache = cache;
        this.rootServer = rootServer;
    }

    public DnsResponse resolve(String name, RecordType type) {
        return resolve(name, type, rootServer, 0);
    }

    private DnsResponse resolve(String name, RecordType type, DnsServerRef server, int depth) {
        if (depth > MAX_DEPTH) {
            return DnsResponse.servfail("Max recursion depth exceeded for " + name);
        }

        DnsResponse cached = cache.get(name, type);
        if (cached != null && !cached.isExpired()) {
            return cached;
        }

        DnsResponse response = server.query(name, type);

        switch (response.kind()) {
            case ANSWER:
                cache.put(name, type, response, response.ttl());
                return response;

            case CNAME:
                // Recurse from the root again for the canonical name target.
                return resolve(response.cnameTarget(), type, rootServer, depth + 1);

            case REFERRAL:
                // Recurse into the more specific server the current one pointed us to.
                return resolve(name, type, response.referredServer(), depth + 1);

            case NXDOMAIN:
            default:
                return response;
        }
    }
}
